insert into public.prompt_examples(id,slug,pattern,domain,difficulty,title,intent,prompt_text,expected_output,recommended_model_snapshot,measurement_status,measured_result,source_refs,last_verified,metadata) values ('prompt-041','few-shot-support','Few-shot','고객지원','초급','고객지원 · Few-shot 패턴','고객 문의를 유형별로 분류하고 해결책을 안내','다음 예시의 판단 기준과 출력 형식을 학습한 뒤 새 입력을 처리하세요.

<example>
입력: 명확하고 근거가 충분한 간단한 사례
출력: {"status":"ok","reason":"근거 확인"}
</example>
<example>
