insert into public.prompt_examples(id,slug,pattern,domain,difficulty,title,intent,prompt_text,expected_output,recommended_model_snapshot,measurement_status,measured_result,source_refs,last_verified,metadata) values ('prompt-123','reasoning-summary','Reasoning scaffold','문서','중급','문서 · Reasoning scaffold 패턴','긴 문서를 의사결정용 요약으로 압축','문제: 긴 문서를 의사결정용 요약으로 압축
입력: {{document}}

출력할 것은 다음뿐입니다.
1. 3~5개 항목의 짧은 실행 계획
2. 필요한 근거·계산·도구
