insert into public.prompt_examples(id,slug,pattern,domain,difficulty,title,intent,prompt_text,expected_output,recommended_model_snapshot,measurement_status,measured_result,source_refs,last_verified,metadata) values ('prompt-141','quick-support','Quick mode','고객지원','초급','고객지원 · Quick mode 패턴','고객 문의를 유형별로 분류하고 해결책을 안내','[QUICK MODE]
