insert into public.prompt_examples(id,slug,pattern,domain,difficulty,title,intent,prompt_text,expected_output,recommended_model_snapshot,measurement_status,measured_result,source_refs,last_verified,metadata) values ('prompt-201','verification-support','Verification','고객지원','중급','고객지원 · Verification 패턴','고객 문의를 유형별로 분류하고 해결책을 안내','초안 작업: 고객 문의를 유형별로 분류하고 해결책을 안내
입력: {{customer_message}}

1차 결과를 만든 뒤 별도 검증 패스를 수행하세요.
검증 항목:
- 입력 근거와 모순이 없는가
- 요구한 출력 형식(분류, 긴급도, 답변 초안, 추가 확인사항)을 지켰는가
