insert into public.prompt_examples(id,slug,pattern,domain,difficulty,title,intent,prompt_text,expected_output,recommended_model_snapshot,measurement_status,measured_result,source_refs,last_verified,metadata) values ('prompt-221','multi-stage-support','Multi-stage','고객지원','고급','고객지원 · Multi-stage 패턴','고객 문의를 유형별로 분류하고 해결책을 안내','복합 작업을 한 번에 쓰지 말고 단계별로 처리하세요.

목표: 고객 문의를 유형별로 분류하고 해결책을 안내
입력: {{customer_message}}

Stage 1 — 필요한 정보만 추출
Stage 2 — 누락/충돌/위험 검증
