insert into public.agent_recipes(id,slug,title,category,difficulty,problem,steps,prompt_template,metrics,source_refs,last_verified,metadata) values ('recipe-001','qa','사내 지식 QA','RAG','중급','사내 지식 QA 업무를 반복 가능하고 검증 가능한 흐름으로 만들기','["query rewrite","retriever","reranker","grounded answer","citation validator"]'::jsonb,'목표: 사내 지식 QA. 각 단계의 입력/출력과 성공 기준을 명시하고, 실패하면 다음 단계로 넘어가지 말고 원인을 표시하세요.','["retrieval recall","faithfulness","citation correctness"]'::jsonb,array['openai-agents','mcp-spec','react-paper']::text[],'2026-09-21'::date,'{"type":"recipe","architecture":"query rewrite → retriever → reranker → grounded answer → citation validator","verification":"각 단계의 trace와 최종 task success를 분리해 기록합니다.","common_failure":"모든 단계를 한 번의 자유형 응답에 맡겨 실패 지점을 추적하지 못하는 것.","security":"쓰기/삭제/외부전송은 최소 권한과 확인 절차를 적용합니다."}'::jsonb) on conflict(id) do update set slug=excluded.slug,title=excluded.title,category=excluded.category,difficulty=excluded.difficulty,problem=excluded.problem,steps=excluded.steps,prompt_template=excluded.prompt_template,metrics=excluded.metrics,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
